			Offset    int    `json:"offset"`
			Limit     int    `json:"limit"`
			Directory string `json:"directory"`
		}

directory := req.Directory
		if directory == "" || !filepath.IsAbs(directory) || directory == "/" {
			directory, _ = os.Getwd()
		}

