JSON.stringify({
        path: args.filePath,
        offset: args.offset ?? 0,
        limit: args.limit ?? 0,
        directory,
      }),

const res = await daemonRequest("POST", "/v1/glob", JSON.stringify({
      pattern: args.pattern,
      path: args.path ?? directory,
      directory,
    }))

-- Seed the daemon's folders gate from opencode.json external_directory once
-- per nvim start (config -> memory). Additive-only; existing rows win.
vim.api.nvim_create_autocmd("VimEnter", {
  callback = function()
    pcall(function()
      folders.import()
    end)
  end,
})

-- R1: focus routing - write the active file so refs match what you work on.

const suggestion = await suggestWorkItem({
        directory,
        session_id: context?.sessionID || "",
        item_id: args.item_id,
        action: args.action,
        payload,
        rationale: args.rationale,
      });
      // Route the review through the standard proposals console (<leader>ap):
      // emit a goal-suggest proposal row into the session journal. Accepting
      // it in the review console applies the suggestion via the daemon.
      const { appendProposal } = await import("../proposals");
      await appendProposal(directory, context?.sessionID || "", {
        operation: "goal-suggest",
        path: String(suggestion.id),
        content: JSON.stringify(
          {
            action: args.action,
            item_id: args.item_id ?? null,
            payload,
            rationale: args.rationale,
          },
          null,
          2,
        ),
        reason: `goal suggestion: ${args.action}${args.item_id ? " #" + args.item_id : ""} — ${args.rationale || "no rationale"}`,
        group: "goal-suggest",
        ts: Date.now(),
        status: "pending",
      });
